{
  "lines": [
    {
      "speaker": "selma-aydn",
      "text": "That is a very reasonable definition of success. Most people want the middle to stay up, but the taste is the part that actually matters."
    },
    {
      "speaker": "",
      "text": "Mika tilts her head slightly, the silver bracelet catching the light as she rests her chin on her hand. She looks at you with a relaxed, open expression, waiting for you to finish your thought or answer her earlier question."
    },
    {
      "speaker": "selma-aydn",
      "text": "So, back to you. Do you have a quiet evening ritual, or is it mostly just... existing?"
    }
  ],
  "summary": "Mika agrees that taste is the important part of baking and gently redirects the conversation back to the player's personal habits, asking about their quiet evening rituals.",
  "end_scene": false,
  "memories": [
    {
      "charKey": "selma-aydn",
      "type": "neutral",
      "desc": "Values practical results (taste) over aesthetic perfection (cake shape) in baking."
    }
  ],
  "facts": [],
  "acts": [
